INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65956099', 65956099, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Balai Besar Pelatihan Vokasi dan Produktivitas Semarang', 'Belanja Bahan Pelatihan Vokasi Bidang Industri dan Jasa Reguler', 'Barang', 'E-Purchasing', 'Jawa Tengah, Semarang (Kota)', 698430000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '27 Paket', 'Bahan Pelatihan: Terdiri dari 14 paket materi untuk berbagai bidang, seperti bahasa asing (Jepang, Mandarin, Korea, Inggris), kecantikan & menjahit, administrasi & bisnis (akuntansi, digital marketing, sekretaris), serta keahlian teknis (Las SMAW, Teknisi AC). Harga paket bervariasi dari Rp13.000.000 hingga Rp68.050.000. Konsumsi Peserta: Dialokasikan untuk kelas dengan rentang durasi 160–380 Jam Pelajaran (JP). Tarif konsumsi seragam, yaitu Rp25.000 per Orang/Hari (OH). Pakaian Kerja: Dianggarkan sebanyak 512 potong dengan harga Rp1.500.000 per potong. Modul Pelatihan: Disediakan 256 buah dengan harga Rp225.000 per buah. Dokumentasi dan Pelaporan: Dianggarkan 16 paket dengan biaya Rp300.000 per paket.', '1. Pakaian Kerja. ( 512, PTG, @ 200000 ); 2. Bahan Pelatihan Bahasa Jepang N5 360 JP ( 1, PKT, @ 18000000 ); 3. Bahan Pelatihan Merias Wajah dan Menata Rambut 300 JP ( 1, PKT, @ 27500000 ); 4. Bahan Pelatihan Merawat dan Menata Rambut Dasar 300 JP ( 1, PKT, @ 22000000 ); 5. Bahan Pelatihan menjahit kebaya 260JP ( 1, PKT, @ 30500000 ); 6. Konsumsi Peserta 160 JP ( 352, OH, @ 25000 ); 7. Konsumsi Peserta 380 JP ( 800, OH, @ 25000 ); 8. Dokumentasi dan Pelaporan ( 16, PKT, @ 300000 ); 9. Bahan Pelatihan Pengelola Admiistrasi Perkantoran 260 JP ( 1, PKT, @ 22000000 ); 10. Bahan Pelatihan Social media officer 260JP ( 1, PKT, @ 22000000 ); 11. Bahan Pelatihan Digital marketing 260JP ( 1, PKT, @ 22000000 ); 12. Bahan Pelatihan Junior sekretaris 340JP ( 1, PKT, @ 28000000 ); 13. Bahan Pelatihan Teknisi Akuntasi Junior 180JP ( 1, PKT, @ 23000000 ); 14. Bahan Pelatihan Junior Administrative Assistant 260 JP ( 1, PKT, @ 18500000 ); 15. Bahan Pelatihan Business Chinese Standard Test (BCT) 380 JP ( 1, PKT, @ 25500000 ); 16. Bahan Pelatihan EPS Topik 1 260 JP ( 1, PKT, @ 17500000 ); 17. Modul ( 256, OP, @ 225000 ); 18. Bahan Pelatihan English for Contact Center Agent 230 JP ( 1, PKT, @ 13000000 ); 19. Bahan Pelatihan Teknisi Perawatan AC Residential 180 JP ( 1, PKT, @ 16500000 ); 20. Bahan Pelatihan Plate welder SMAW 3G UP/PF 340 JP ( 1, PKT, @ 68050000 ); 21. Bahan Pelatihan Merias Wajah 160 JP ( 1, PKT, @ 16500000 ); 22. Konsumsi Peserta 180 JP ( 800, OH, @ 25000 ); 23. Konsumsi Peserta 230JP ( 480, OH, @ 25000 ); 24. Konsumsi Peserta 260JP ( 3360, OH, @ 25000 ); 25. Konsumsi Peserta 300JP ( 1280, OH, @ 25000 ); 26. Konsumsi Peserta 340 JP ( 1440, OH, @ 25000 ); 27. Konsumsi Peserta 360JP ( 1504, OH, @ 25000 );', 665600000, 'high', 'Terdapat indikasi kuat ketidakwajaran pada penganggaran pakaian kerja. Uraian mencantumkan 512 potong dengan harga Rp1.500.000 per potong, namun spesifikasi rinci menunjukkan harga satuan Rp200.000 per potong. Selisih ini menimbulkan potensi pemborosan sekitar Rp665,6 juta. Komponen lain seperti konsumsi, modul, dan bahan pelatihan masih tampak selaras dengan kegiatan pelatihan vokasi.', NULL, NULL, 3, 1, 1, 1, 1, 2458337);
